<style> .detail-card { background:#fff; border-radius:8px; padding:24px; box-shadow:0 1px 6px rgba(0,0,0,0.06); } .detail-card h2 { margin-bottom:16px; } .detail-grid { display:grid; grid-template-columns:1fr 1fr; gap:12px; } .detail-item { padding:8px 0; border-bottom:1px solid #f0f0f0; } .detail-item .label { font-size:12px; color:#888; text-transform:uppercase; } .detail-item .value { font-size:15px; font-weight:500; margin-top:2px; } .detail-full { padding:8px 0; border-bottom:1px solid #f0f0f0; grid-column:1/-1; } .badge { display:inline-block; padding:2px 8px; border-radius:4px; font-size:12px; font-weight:500; } .badge-draf { background:#fff3e0; color:#e65100; } .badge-submitted { background:#e3f2fd; color:#1565c0; } .badge-verified { background:#e8f5e9; color:#2e7d32; } .badge-rejected { background:#fce4ec; color:#c62828; } .badge-archived { background:#f5f5f5; color:#888; } .action-group { margin-top:24px; display:flex; gap:12px; flex-wrap:wrap; } .btn { padding:8px 20px; border:none; border-radius:6px; font-size:14px; font-weight:600; cursor:pointer; text-decoration:none; display:inline-block; } .btn-primary { background:#1a73e8; color:#fff; } .btn-success { background:#2e7d32; color:#fff; } .btn-danger { background:#c62828; color:#fff; } .btn-secondary { background:#e0e0e0; color:#333; } .btn:hover { opacity:0.9; } @media (max-width:640px) { .detail-grid { grid-template-columns:1fr; } } </style> <div class="detail-card"> <h2>Detail Laporan Hama</h2> <div class="detail-grid"> <div class="detail-item"> <div class="label">Nomor Laporan</div> <div class="value"><?= $laporan['nomor_laporan'] !== null ? \App\Core\Security::e($laporan['nomor_laporan']) : '<span style="color:#999">Belum dibuat</span>' ?></div> </div> <div class="detail-item"> <div class="label">Status</div> <div class="value"><span class="badge badge-<?= strtolower($laporan['status']) ?>"><?= \App\Core\Security::e($laporan['status']) ?></span></div> </div> <div class="detail-item"> <div class="label">Tanggal</div> <div class="value"><?= \App\Core\Security::e($laporan['tanggal'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">OPT</div> <div class="value"><?= \App\Core\Security::e($laporan['nama_opt'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">Kabupaten</div> <div class="value"><?= \App\Core\Security::e($laporan['nama_kabupaten'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">Kecamatan</div> <div class="value"><?= \App\Core\Security::e($laporan['nama_kecamatan'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">Desa</div> <div class="value"><?= \App\Core\Security::e($laporan['nama_desa'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">Tingkat Keparahan</div> <div class="value"><?= \App\Core\Security::e($laporan['tingkat_keparahan'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">Luas Serangan (Ha)</div> <div class="value"><?= $laporan['luas_serangan'] !== null ? \App\Core\Security::e((string) $laporan['luas_serangan']) : '-' ?></div> </div> <div class="detail-item"> <div class="label">Populasi</div> <div class="value"><?= $laporan['populasi'] !== null ? \App\Core\Security::e((string) $laporan['populasi']) : '-' ?></div> </div> <div class="detail-item"> <div class="label">Latitude</div> <div class="value"><?= $laporan['latitude'] !== null ? \App\Core\Security::e((string) $laporan['latitude']) : '-' ?></div> </div> <div class="detail-item"> <div class="label">Longitude</div> <div class="value"><?= $laporan['longitude'] !== null ? \App\Core\Security::e((string) $laporan['longitude']) : '-' ?></div> </div> <div class="detail-item"> <div class="label">Lokasi</div> <div class="value"><?= \App\Core\Security::e($laporan['lokasi'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">Pelapor</div> <div class="value"><?= \App\Core\Security::e($laporan['pelapor_nama'] ?? '-') ?> (@<?= \App\Core\Security::e($laporan['pelapor_username'] ?? '-') ?>)</div> </div> <div class="detail-item"> <div class="label">Verifikator</div> <div class="value"><?= \App\Core\Security::e($laporan['verifikator_nama'] ?? '-') ?></div> </div> <div class="detail-item"> <div class="label">Dibuat</div> <div class="value"><?= date('d/m/Y H:i', strtotime($laporan['created_at'])) ?></div> </div> <div class="detail-item"> <div class="label">Diperbarui</div> <div class="value"><?= date('d/m/Y H:i', strtotime($laporan['updated_at'])) ?></div> </div> <div class="detail-full"> <div class="label">Alamat Lengkap</div> <div class="value" style="font-weight:400;"><?= \App\Core\Security::e($laporan['alamat_lengkap'] ?? '-') ?></div> </div> <?php if (!empty($laporan['foto_url'])): ?> <div class="detail-full"> <div class="label">Foto</div> <div class="value" style="font-weight:400;"><img src="/<?= \App\Core\Security::e($laporan['foto_url']) ?>" alt="Foto Laporan" style="max-width:400px;max-height:300px;border-radius:6px;border:1px solid #e0e0e0;"></div> </div> <?php endif; ?> <div class="detail-full"> <div class="label">Catatan</div> <div class="value" style="font-weight:400;white-space:pre-wrap;"><?= \App\Core\Security::e($laporan['catatan'] ?? '-') ?></div> </div> </div> <?php if ($laporan['verified_by'] !== null || $laporan['catatan_verifikasi'] !== null): ?> <div style="margin-top:16px;padding:12px 16px;background:#f8f9fa;border-radius:6px;border-left:4px solid #1a73e8;"> <div style="font-size:13px;color:#555;font-weight:600;margin-bottom:8px;">INFORMASI VERIFIKASI</div> <?php if ($laporan['verified_at'] !== null): ?> <div style="font-size:13px;margin-bottom:4px;"><strong>Waktu:</strong> <?= date('d/m/Y H:i', strtotime($laporan['verified_at'])) ?></div> <?php endif; ?> <?php if ($laporan['catatan_verifikasi'] !== null && $laporan['catatan_verifikasi'] !== ''): ?> <div style="font-size:13px;margin-bottom:4px;"><strong>Catatan:</strong> <?= \App\Core\Security::e($laporan['catatan_verifikasi']) ?></div> <?php endif; ?> <?php if ($laporan['status'] === 'Ditolak'): ?> <div style="font-size:13px;margin-top:4px;padding:8px 12px;background:#fce4ec;border-radius:4px;color:#c62828;"> <strong>Alasan penolakan:</strong> <?= \App\Core\Security::e($laporan['catatan_verifikasi'] ?? '-') ?> </div> <?php endif; ?> </div> <?php endif; ?> <div class="action-group"> <a href="/laporan-hama" class="btn btn-secondary">Kembali ke Daftar</a> <?php if ($laporan['status'] === 'Draf' && $currentUser['role'] === 'petugas'): ?> <a href="/laporan-hama/<?= (int) $laporan['id'] ?>/edit" class="btn btn-primary">Edit</a> <form method="POST" action="/laporan-hama/<?= (int) $laporan['id'] ?>/submit" style="display:inline"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn btn-success">Kirim Laporan</button> </form> <form method="POST" action="/laporan-hama/<?= (int) $laporan['id'] ?>/delete" style="display:inline" onsubmit="return confirm('Hapus draf ini?')"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn btn-danger">Hapus</button> </form> <?php endif; ?> <?php if ($laporan['status'] === 'Submitted' && $currentUser['role'] === 'admin'): ?> <form method="POST" action="/laporan-hama/<?= (int) $laporan['id'] ?>/verifikasi" style="display:inline"> <?= \App\Core\Security::csrfField() ?> <input type="hidden" name="catatan_verifikasi" value=""> <button type="submit" class="btn btn-success" onclick="return confirm('Verifikasi laporan ini?')">Verifikasi</button> </form> <button type="button" class="btn btn-danger" onclick="document.getElementById('tolak-form-<?= (int) $laporan['id'] ?>').style.display='block'">Tolak</button> <div id="tolak-form-<?= (int) $laporan['id'] ?>" style="display:none;margin-top:8px;width:100%;"> <form method="POST" action="/laporan-hama/<?= (int) $laporan['id'] ?>/tolak" style="display:flex;gap:8px;align-items:flex-start;"> <?= \App\Core\Security::csrfField() ?> <textarea name="alasan" placeholder="Alasan penolakan (min. 10 karakter)..." required minlength="10" style="flex:1;padding:8px;border:1px solid #d0d0d0;border-radius:4px;font-size:13px;min-height:60px;"></textarea> <button type="submit" class="btn btn-danger" style="white-space:nowrap;">Kirim</button> </form> </div> <?php endif; ?> <?php if ($laporan['status'] === 'Diverifikasi' && $currentUser['role'] === 'admin'): ?> <form method="POST" action="/laporan-hama/<?= (int) $laporan['id'] ?>/archive" style="display:inline"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn btn-secondary" onclick="return confirm('Arsipkan laporan ini?')">Arsipkan</button> </form> <?php endif; ?> <?php if ($laporan['status'] === 'Ditolak' && $currentUser['role'] === 'petugas'): ?> <a href="/laporan-hama/<?= (int) $laporan['id'] ?>/edit" class="btn btn-primary">Edit &amp; Perbaiki</a> <form method="POST" action="/laporan-hama/<?= (int) $laporan['id'] ?>/resubmit" style="display:inline"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn btn-success" onclick="return confirm('Kirim ulang laporan ini?')">Kirim Ulang</button> </form> <?php endif; ?> </div> </div> 